def compute_order_amount(current_inventory, pipeline_inventory, history_demand, holding_cost, lost_sales_cost, lead_time):
    if len(history_demand) < 2:
        return max(0, 100 - current_inventory - sum(pipeline_inventory))

    avg_demand = sum(history_demand) / len(history_demand)
    std_dev = (sum((d - avg_demand)**2 for d in history_demand) / len(history_demand))**0.5
    safety_stock = std_dev * (lead_time**0.5) * (lost_sales_cost / (holding_cost + lost_sales_cost))

    incoming_inventory = sum(pipeline_inventory)
    projected_inventory = current_inventory + incoming_inventory - avg_demand
    order_amount = max(0, avg_demand + safety_stock - projected_inventory)

    return order_amount

def compute_order_amount(current_inventory, pipeline_inventory, history_demand, holding_cost, lost_sales_cost, lead_time):
    if not history_demand:
        return max(0, 100 - current_inventory)

    cost_ratio = lost_sales_cost / (holding_cost + lost_sales_cost)
    demand_percentile = int(100 * cost_ratio)
    forecast_demand = sorted(history_demand)[-1] if cost_ratio >= 1.0 else sorted(history_demand)[min(int(len(history_demand) * cost_ratio), len(history_demand)-1)]

    pipeline_sum = sum(pipeline_inventory)
    target_level = forecast_demand * (lead_time + 1)

    order_amount = max(0, target_level - current_inventory - pipeline_sum)
    return order_amount

def compute_order_amount(current_inventory, pipeline_inventory, history_demand, holding_cost, lost_sales_cost, lead_time):
    if not history_demand:
        return max(0, 100 - current_inventory - sum(pipeline_inventory))

    alpha = 0.3  # Smoothing factor
    forecast = history_demand[0]
    for d in history_demand[1:]:
        forecast = alpha * d + (1 - alpha) * forecast

    service_level = lost_sales_cost / (holding_cost + lost_sales_cost)
    safety_stock = (sum((d - forecast)**2 for d in history_demand[-10:]) / min(10, len(history_demand)))**0.5 * (lead_time**0.5) * service_level

    incoming_inventory = sum(pipeline_inventory)
    reorder_point = forecast * lead_time + safety_stock
    order_amount = max(0, reorder_point - current_inventory - incoming_inventory + forecast)

    return order_amount
